    private suspend fun reference(c:InboxConversationFilesContext,id:Int=8101):QualifiedMemberReference? {val s=MemberReferenceSession();s.bind(c);s.show();s.update("00$id",s.input);val t=s.begin(s.control)!!;s.accept(members().member(c.business,id),t);s.use(s.control);return s.state.choice}
