    private class Held(override val grants:List<SyntheticInboxTargetAssignmentGrant>,override val targetMemberships:List<SyntheticInboxTargetMembershipContext>):SyntheticInboxTargetAssignmentPort {val attempts=mutableListOf<InboxTargetAssignmentAttempt>();val pending=mutableListOf<CompletableDeferred<SyntheticInboxTargetAssignmentOutcome>>();override suspend fun execute(a:InboxTargetAssignmentAttempt):SyntheticInboxTargetAssignmentOutcome {attempts+=a;return withContext(NonCancellable){CompletableDeferred<SyntheticInboxTargetAssignmentOutcome>().also {pending+=it}.await()}}}
    @Test fun exactAssignmentSourceSeparateActorTargetUserContextsBodyReceiptAndUnknown()=runTest {
        val d=JSONObject(fixture("inbox-target-assignment"));val f=FixtureInboxTargetAssignmentPort.fromJSON(fixture("inbox-target-assignment"));val c=context(d.getJSONObject("context"));val s=InboxTargetAssignmentSource.decode(d.getString("source_json"),c)!!;val ref=reference(c)!!;val auth=f.grants[0].authorization(c)!!;val target=f.targetMemberships.first {it.matches(ref)};val candidate=InboxTargetAssignmentCandidate.make(s,ref)!!;val review=InboxTargetAssignmentReview(s,auth,candidate,target,1)
        val cases=d.getJSONArray("source_cases");for(i in 0 until cases.length()){val x=cases.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxTargetAssignmentSource.decode(x.getString("response_json"),context(x.getJSONObject("context")))!=null)}
        val grants=d.getJSONArray("grant_cases");for(i in 0 until grants.length()){val x=grants.getJSONObject(i);val g=x.getJSONObject("grant");assertEquals(x.getBoolean("valid"),SyntheticInboxTargetAssignmentGrant(g.getInt("business"),g.getInt("conversation"),g.getInt("actor"),g.getBoolean("manage")).authorization(c)!=null)}
        val targets=d.getJSONArray("target_cases");for(i in 0 until targets.length()){val x=targets.getJSONObject(i);val t=x.getJSONObject("target");val v=SyntheticInboxTargetMembershipContext(t.getInt("business"),t.getInt("user"),t.getBoolean("active_member"));assertEquals(x.getBoolean("valid"),v.matches(ref));assertEquals(x.getBoolean("valid"),review.copy(targetMembership=v).valid)}
        assertEquals(8101,ref.source.id);assertEquals(5002,ref.source.user.id);assertEquals("008101",ref.rawInput);assertNull(reference(c,8102));assertEquals(5004,reference(c,8103)!!.source.user.id)
        for(next in listOf(c.copy(conversation=902),c.copy(epoch=701),c.copy(revision=2),c.copy(business=202,conversation=951))){assertNull(InboxTargetAssignmentCandidate.make(s,reference(next,if(next.business==101)8101 else 9101)!!))}
        val l=InboxTargetAssignmentLedger();val a=l.begin(review)!!;val body=JSONObject(a.preparedBody());assertEquals(setOf("user_id"),body.keys().asSequence().toSet());assertEquals(5002,body.getInt("user_id"));assertEquals("/api/inbox/conversations/901/assign/",a.path);assertTrue(a.query.isEmpty());assertTrue(a.headers.isEmpty());assertNull(l.begin(review));assertFalse(l.acknowledge(auth,l.visible(auth)!!))
        val receipts=d.getJSONArray("receipt_cases");for(i in 0 until receipts.length()){val x=receipts.getJSONObject(i);assertEquals(x.getString("name"),x.getBoolean("valid"),InboxTargetAssignmentReceipt.decode(x.getString("response_json"),a)!=null)}
        l.complete(a,f.execute(a));val known=l.visible(auth)!!;assertEquals(InboxTargetAssignmentPhase.RESPONSE,known.phase);assertEquals(5002,known.result!!.source.assignedTo);assertEquals(7000,known.attempt.review.source.assignedTo);l.complete(a,SyntheticInboxTargetAssignmentOutcome.Unknown);assertEquals(known,l.visible(auth));assertTrue(l.acknowledge(auth,known))
        val u=l.begin(review)!!;l.complete(u,SyntheticInboxTargetAssignmentOutcome.Unknown);val unknown=l.visible(auth)!!;val next=c.copy(epoch=702,revision=2);val nr=reference(next,8103)!!;val ns=InboxTargetAssignmentSource.decode(JSONObject().put("id",901).put("business",101).put("assigned_to",5002).put("updated_at","matching GET").toString(),next)!!;val na=f.grants[0].authorization(next)!!;assertEquals(unknown,l.visible(na));assertFalse(l.acknowledge(na,unknown));assertNull(l.begin(InboxTargetAssignmentReview(ns,na,InboxTargetAssignmentCandidate.make(ns,nr)!!,f.targetMemberships.first {it.matches(nr)},2)));assertEquals(ref,unknown.attempt.review.candidate.reference)
        assertNull(l.visible(SyntheticInboxTargetAssignmentGrant(101,901,6001,true).authorization(next)));assertTrue(l.blocked(101,901));assertFalse(l.blocked(202,951))
        for(status in listOf(201,202,204,400,403,409,500)){val ledger=InboxTargetAssignmentLedger();val attempt=ledger.begin(review)!!;ledger.complete(attempt,SyntheticInboxTargetAssignmentOutcome.Response(status,JSONObject().put("id",901).put("business",101).put("assigned_to",5002).put("updated_at","synthetic").toString()));assertEquals(InboxTargetAssignmentPhase.UNKNOWN,ledger.visible(auth)!!.phase)}
        val reject=InboxTargetAssignmentLedger();val ra=reject.begin(review)!!;reject.complete(ra,SyntheticInboxTargetAssignmentOutcome.RejectedWithoutWrite);assertTrue(reject.acknowledge(auth,reject.visible(auth)!!));assertEquals(1,reject.records.size)
    }
    private inner class Reads:InboxRepository {override suspend fun inbox(business:Int)=JsonContracts.inbox(fixture("inbox-$business"));override suspend fun thread(business:Int,id:Int)=JsonContracts.thread(fixture("inbox-$business-$id"))}
    @Test fun actualParentFrozenMemberVsUserKnownUnknownMatchingRereadAndABA()=runTest {
        Dispatchers.setMain(StandardTestDispatcher(testScheduler));val f=FixtureInboxTargetAssignmentPort.fromJSON(fixture("inbox-target-assignment"));val held=Held(f.grants,f.targetMemberships);var matching=false;val get=FixtureInboxTargetAssignmentReadTransport.fromJSON(fixture("inbox-target-assignment"));val src=APIInboxTargetAssignmentRepository(ReadTransport {q->if(matching && q.path=="/api/inbox/conversations/901/")ReadResponse(200,JSONObject().put("id",901).put("business",101).put("assigned_to",5004).put("updated_at","matching GET").toString())else get.get(q)})
        val m=InboxViewModel(Reads(),files=files(),assignmentRead=APIInboxSelfAssignmentRepository(FixtureInboxSelfAssignmentReadTransport.fromJSON(fixture("inbox-self-assignment"))),assignmentSubmission=FixtureInboxSelfAssignmentPort.fromJSON(fixture("inbox-self-assignment")),members=members(),targetAssignmentRead=src,targetAssignmentSubmission=held)
        try {m.load(101,700);runCurrent();m.open(901);runCurrent();val original=m.state.thread;val box=m.fileMetadata!!;val link=box.targetAssignment!!;val p=box.memberReference!!;m.openFiles(m.filesEntryControl);assertNull(link.source);assertNull(p.state.source);link.load(link.control);val stale=link.control;p.update("008101",p.input);p.read(p.control);link.prepare(link.control);assertNull(link.review);p.use(p.control);link.prepare(stale);assertNull(link.review);assertTrue(link.canPrepare);link.prepare(link.control);val r=link.review;val chosen=p.state.choice;p.clearChoice(p.control);p.clear(p.control);p.update("008103",p.input);p.read(p.control);box.loadAssignment(box.control);box.prepareAssignment(box.control);assertEquals(r,link.review);assertEquals(chosen,p.state.choice);assertNull(box.assignmentReview);assertTrue(link.canSubmit);link.back(link.control);assertEquals(chosen,p.state.choice);assertFalse(p.controlsBlocked());link.prepare(link.control);val control=link.control;val job=launch {link.submit(control)};runCurrent();val pending=link.record!!;link.submit(link.control);link.acknowledge(pending,link.control);box.load(box.control);assertEquals(chosen,p.state.choice);assertEquals(1,held.attempts.size);assertTrue(m.conversationCommandsBlocked);assertTrue(p.controlsBlocked());m.closeFiles(m.filesPresentationControl);m.openFiles(m.filesEntryControl);held.pending[0].complete(f.execute(held.attempts[0]));job.join();val response=link.record!!;assertEquals(InboxTargetAssignmentPhase.RESPONSE,response.phase);assertEquals(5002,response.result!!.source.assignedTo);assertEquals(8101,response.attempt.review.candidate.reference.source.id);assertEquals(original,m.state.thread);link.acknowledge(response,control);assertEquals(response,link.record);link.acknowledge(response,link.control);assertNull(link.source);assertNull(p.state.choice);assertEquals(1,link.retainedAttemptCount);assertFalse(m.conversationCommandsBlocked)
            link.load(link.control);choose(p,8103);link.prepare(link.control);val unknownJob=launch {link.submit(link.control)};runCurrent();held.pending[1].completeExceptionally(IllegalStateException("fake unknown"));unknownJob.join();val unknown=link.record!!;matching=true;link.load(link.control);choose(p,8101);link.acknowledge(unknown,link.control);link.prepare(link.control);assertEquals(5004,link.source!!.assignedTo);assertEquals(5004,unknown.attempt.review.candidate.reference.source.user.id);assertEquals("008103",unknown.attempt.review.candidate.reference.rawInput);assertEquals(unknown,link.record);assertFalse(link.canPrepare);box.loadAssignment(box.control);box.prepareAssignment(box.control);assertNull(box.assignmentReview)
            m.closeFiles(m.filesPresentationControl);m.load(202,701);runCurrent();m.open(951);runCurrent();m.openFiles(m.filesEntryControl);assertNull(link.record);assertEquals("",p.state.rawInput);m.closeFiles(m.filesPresentationControl);m.load(101,702);runCurrent();m.open(901);runCurrent();m.openFiles(m.filesEntryControl);assertEquals(unknown,link.record);assertTrue(m.conversationCommandsBlocked)
        }finally{Dispatchers.resetMain()}
    }
    @Test fun missingSeparateContextsInactiveMemberCancellationAndLateOwner()=runTest {
        val f=FixtureInboxTargetAssignmentPort.fromJSON(fixture("inbox-target-assignment"));val a=InboxConversationFilesContext(101,901,703,1);val b=InboxConversationFilesContext(202,951,704,1)
        suspend fun ready(port:SyntheticInboxTargetAssignmentPort?,id:Int=8101):InboxTargetAssignmentModel {val p=MemberReferenceModel(members());p.bind(a);p.show();val m=InboxTargetAssignmentModel(source(),p,port);m.commandsBlocked={false};m.bind(a);m.show();m.load(m.control);choose(p,id);return m}
        for(port in listOf(null,Held(emptyList(),f.targetMemberships),Held(listOf(SyntheticInboxTargetAssignmentGrant(101,901,5001,false)),f.targetMemberships),Held(f.grants,emptyList()),Held(f.grants,listOf(SyntheticInboxTargetMembershipContext(101,8101,true))),Held(f.grants,listOf(SyntheticInboxTargetMembershipContext(101,5002,false))),Held(f.grants,listOf(SyntheticInboxTargetMembershipContext(202,5002,true))))){val m=ready(port);m.prepare(m.control);assertNotNull(m.source);assertNotNull(m.picker!!.state.choice);assertNull(m.review);assertEquals(0,m.retainedAttemptCount)}
        val inactive=ready(f,8102);inactive.prepare(inactive.control);assertFalse(inactive.picker!!.state.source!!.isActive);assertNull(inactive.review)
        val cp=Held(f.grants,f.targetMemberships);val cancel=ready(cp);cancel.prepare(cancel.control);val cj=launch {cancel.submit(cancel.control)};runCurrent();cj.cancel();cp.pending[0].complete(f.execute(cp.attempts[0]));cj.join();assertEquals(InboxTargetAssignmentPhase.UNKNOWN,cancel.record!!.phase);assertEquals(cp.attempts[0],cancel.record!!.attempt)
        val lp=Held(f.grants,f.targetMemberships);val late=ready(lp);late.prepare(late.control);val lj=launch {late.submit(late.control)};runCurrent();late.hide();late.picker!!.bind(b);late.picker!!.show();late.bind(b);late.show();late.load(late.control);late.picker!!.update("009101",late.picker!!.input);val before=late.control;lp.pending[0].complete(f.execute(lp.attempts[0]));lj.join();assertEquals(before,late.control);assertEquals("009101",late.picker!!.state.rawInput);assertNull(late.record);assertEquals(1,late.retainedAttemptCount)
        val oldSource=source().source(a);val deferred=CompletableDeferred<InboxTargetAssignmentSource>();val p=MemberReferenceModel(members());val m=InboxTargetAssignmentModel(object:InboxTargetAssignmentRepository {override suspend fun source(c:InboxConversationFilesContext)=withContext(NonCancellable){deferred.await()}},p,f);p.bind(a);p.show();m.bind(a);m.show();val task=launch {m.load(m.control)};runCurrent();m.hide();p.bind(b);p.show();m.bind(b);m.show();val current=m.control;deferred.complete(oldSource);task.join();assertEquals(current,m.control);assertNull(m.source)
        assertNull(InboxConversationFilesModel(files(),ownerScope=this).targetAssignment)
    }
