        val own=container();val link=own.targetAssignment!!;link.load(link.control);choose(own.memberReference!!,8101);link.prepare(link.control);val job=launch {link.submit(link.control)};runCurrent();held.pending[0].complete(SyntheticInboxTargetAssignmentOutcome.Unknown);job.join();val client=own.linkClient!!;client.load(client.control);client.open(client.control);assertFalse(client.canOpen);val lead=own.linkLead!!;lead.load(lead.control);val p=own.leadReference!!;p.search(p.control);p.open(3701,p.control);p.use(p.control);lead.prepare(lead.control);assertFalse(lead.canPrepare);assertNull(lead.review)
        val unknownClient=object:SyntheticInboxLinkClientPort {override val grants=clientFixture.grants;override suspend fun execute(a:InboxLinkClientAttempt)=SyntheticInboxLinkClientOutcome.Unknown};val fromClient=container(clientPort=unknownClient,targetPort=f);val cl=fromClient.linkClient!!;cl.load(cl.control);cl.open(cl.control);cl.search(cl.control,cl.picker!!.control);runCurrent();cl.openClient(1701,cl.control,cl.picker!!.control);runCurrent();cl.useClient(cl.control,cl.picker!!.control);cl.prepare(cl.control);cl.submit(cl.control);val dc=fromClient.targetAssignment!!;dc.load(dc.control);choose(fromClient.memberReference!!,8101);dc.prepare(dc.control);assertFalse(dc.canPrepare);assertNull(dc.review)
        val unknownLead=object:SyntheticInboxLinkLeadPort {override val grants=leadFixture.grants;override suspend fun execute(a:InboxLinkLeadAttempt)=SyntheticInboxLinkLeadOutcome.Unknown};val fromLead=container(leadPort=unknownLead,targetPort=f);val ll=fromLead.linkLead!!;ll.load(ll.control);val pl=fromLead.leadReference!!;pl.search(pl.control);pl.open(3701,pl.control);pl.use(pl.control);ll.prepare(ll.control);ll.submit(ll.control);val dl=fromLead.targetAssignment!!;dl.load(dl.control);choose(fromLead.memberReference!!,8101);dl.prepare(dl.control);assertFalse(dl.canPrepare);assertNull(dl.review);assertTrue(fromLead.blocksCommands(101,901))
        val deal=own.linkDeal!!;deal.load(deal.control);val pd=own.dealReference!!;pd.update("005701",pd.input);pd.read(pd.control);pd.use(pd.control);deal.prepare(deal.control);assertFalse(deal.canPrepare);assertNull(deal.review)
        val unknownDeal=object:SyntheticInboxLinkDealPort {override val grants=dealFixture.grants;override suspend fun execute(a:InboxLinkDealAttempt)=SyntheticInboxLinkDealOutcome.Unknown};val fromDeal=container(targetPort=f,dealPort=unknownDeal);val ld=fromDeal.linkDeal!!;ld.load(ld.control);val rp=fromDeal.dealReference!!;rp.update("005701",rp.input);rp.read(rp.control);rp.use(rp.control);ld.prepare(ld.control);ld.submit(ld.control);val target=fromDeal.targetAssignment!!;target.load(target.control);choose(fromDeal.memberReference!!,8101);target.prepare(target.control);assertFalse(target.canPrepare);assertNull(target.review);assertTrue(fromDeal.blocksCommands(101,901))
